package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API66 counter assertions admitted by Salesforce SF170.
func TestEventPublishCountersAPI66Proof(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeEventCounters66Proof.cls"), "@IsTest private class GladeEventCounters66Proof {\n private static Map<String,Object> observe(String name,List<SObject> events) {\n  Integer dmlBefore=Limits.getDmlStatements();\n  Integer rowsBefore=Limits.getDmlRows();\n  Integer immediateBefore=Limits.getPublishImmediateDML();\n  Map<String,Object> row=new Map<String,Object>{'name'=>name};\n  try {\n   List<Database.SaveResult> results=EventBus.publish(events);\n   row.put('resultCount',results.size());\n   List<Boolean> successes=new List<Boolean>();\n   List<String> errors=new List<String>();\n   for(Database.SaveResult result:results) {\n    successes.add(result.isSuccess());\n    for(Database.Error error:result.getErrors()) errors.add(error.getMessage());\n   }\n   row.put('successes',successes);\n   row.put('errors',errors);\n  } catch(Exception error) {\n   row.put('exceptionType',error.getTypeName());\n   row.put('exceptionMessage',error.getMessage());\n  }\n  row.put('dmlStatements',Limits.getDmlStatements()-dmlBefore);\n  row.put('dmlRows',Limits.getDmlRows()-rowsBefore);\n  row.put('publishImmediateDml',Limits.getPublishImmediateDML()-immediateBefore);\n  return row;\n }\n @IsTest static void immediateAfterCommitAndMixedCounters() {\n  List<Object> rows=new List<Object>();\n  rows.add(observe('immediate-one',new List<SObject>{new GladeImmediateCounter66__e()}));\n  rows.add(observe('aftercommit-one',new List<SObject>{new GladeAfterCounter66__e()}));\n  rows.add(observe('immediate-two',new List<SObject>{new GladeImmediateCounter66__e(),new GladeImmediateCounter66__e()}));\n  rows.add(observe('aftercommit-two',new List<SObject>{new GladeAfterCounter66__e(),new GladeAfterCounter66__e()}));\n  rows.add(observe('mixed-two',new List<SObject>{new GladeImmediateCounter66__e(),new GladeAfterCounter66__e()}));\n  System.assertEquals(5,rows.size());\n  Map<String,Object> row0=(Map<String,Object>)rows[0];\n  System.assertEquals('immediate-one',row0.get('name'));\n  System.assertEquals(1,row0.get('dmlStatements'));\n  System.assertEquals(1,row0.get('dmlRows'));\n  System.assertEquals(0,row0.get('publishImmediateDml'));\n  System.assertEquals(1,row0.get('resultCount'));\n  System.assertEquals(new List<Boolean>{true},row0.get('successes'));\n  Map<String,Object> row1=(Map<String,Object>)rows[1];\n  System.assertEquals('aftercommit-one',row1.get('name'));\n  System.assertEquals(1,row1.get('dmlStatements'));\n  System.assertEquals(1,row1.get('dmlRows'));\n  System.assertEquals(0,row1.get('publishImmediateDml'));\n  System.assertEquals(1,row1.get('resultCount'));\n  System.assertEquals(new List<Boolean>{true},row1.get('successes'));\n  Map<String,Object> row2=(Map<String,Object>)rows[2];\n  System.assertEquals('immediate-two',row2.get('name'));\n  System.assertEquals(1,row2.get('dmlStatements'));\n  System.assertEquals(2,row2.get('dmlRows'));\n  System.assertEquals(0,row2.get('publishImmediateDml'));\n  System.assertEquals(2,row2.get('resultCount'));\n  System.assertEquals(new List<Boolean>{true,true},row2.get('successes'));\n  Map<String,Object> row3=(Map<String,Object>)rows[3];\n  System.assertEquals('aftercommit-two',row3.get('name'));\n  System.assertEquals(1,row3.get('dmlStatements'));\n  System.assertEquals(2,row3.get('dmlRows'));\n  System.assertEquals(0,row3.get('publishImmediateDml'));\n  System.assertEquals(2,row3.get('resultCount'));\n  System.assertEquals(new List<Boolean>{true,true},row3.get('successes'));\n  Map<String,Object> row4=(Map<String,Object>)rows[4];\n  System.assertEquals('mixed-two',row4.get('name'));\n  System.assertEquals(1,row4.get('dmlStatements'));\n  System.assertEquals(2,row4.get('dmlRows'));\n  System.assertEquals(0,row4.get('publishImmediateDml'));\n  System.assertEquals(2,row4.get('resultCount'));\n  System.assertEquals(new List<Boolean>{true,true},row4.get('successes'));\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeEventCounters66Proof.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>66.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeImmediateCounter66__e/GladeImmediateCounter66__e.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><eventType>HighVolume</eventType><label>GladeImmediateCounter66__e</label><pluralLabel>GladeImmediateCounter66__e Records</pluralLabel><publishBehavior>PublishImmediately</publishBehavior></CustomObject>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/objects/GladeAfterCounter66__e/GladeAfterCounter66__e.object-meta.xml"), "<CustomObject xmlns=\"http://soap.sforce.com/2006/04/metadata\"><deploymentStatus>Deployed</deploymentStatus><eventType>HighVolume</eventType><label>GladeAfterCounter66__e</label><pluralLabel>GladeAfterCounter66__e Records</pluralLabel><publishBehavior>PublishAfterCommit</publishBehavior></CustomObject>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"namespace\": \"\", \"sourceApiVersion\": \"66.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{NoDiskCache: true})
	data, _ := json.Marshal(run)
	if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Errors != 0 || got.Skipped != 0 {
		t.Fatalf("event counters: %s", data)
	}
}
